function validate([tires, changeTime, numLaps]) {
  if (!Array.isArray(tires) || tires.length < 1 || tires.length > 100000) return 'tires needs 1 to 100000 entries.';
  if (tires.some(t => !Array.isArray(t) || t.length !== 2)) return 'Each tire is a pair [f, r].';
  if (tires.some(([f]) => !Number.isInteger(f) || f < 1 || f > 100000)) return 'Each f is between 1 and 100000.';
  if (tires.some(([, r]) => !Number.isInteger(r) || r < 2 || r > 100000)) return 'Each r is between 2 and 100000.';
  if (!Number.isInteger(changeTime) || changeTime < 1 || changeTime > 100000) return 'changeTime is between 1 and 100000.';
  if (!Number.isInteger(numLaps) || numLaps < 1 || numLaps > 1000) return 'numLaps is between 1 and 1000.';
  return null;
}

