function minimumFinishTime(tires, changeTime, numLaps) {
  const stint = new Array(numLaps + 1).fill(Infinity);
  for (const [f, r] of tires) {
    let lapTime = f;
    let total = 0;
    for (let laps = 1; laps <= numLaps && lapTime <= f + changeTime; laps++) {
      total += lapTime;
      stint[laps] = Math.min(stint[laps], total);
      lapTime *= r;
    }
  }

  const dp = new Array(numLaps + 1).fill(Infinity);
  dp[0] = 0;
  for (let i = 1; i <= numLaps; i++) {
    for (let k = 1; k <= i && stint[k] < Infinity; k++) {
      dp[i] = Math.min(dp[i], dp[i - k] + stint[k] + changeTime);
    }
  }
  return dp[numLaps] - changeTime;
}

