function minimumFinishTime(tires, changeTime, numLaps) {
  // finish[i]: least time for the first i laps, ending right after a stint.
  const finish = [0];
  for (let i = 1; i <= numLaps; i++) {
    let bestHere = Infinity;
    for (const [f, r] of tires) {
      let lap = f;
      let run = 0;
      for (let k = 1; k <= i; k++) {
        run += lap;
        const cost = finish[i - k] + run + (i - k > 0 ? changeTime : 0);
        if (cost < bestHere) bestHere = cost;
        lap *= r;
      }
    }
    finish.push(bestHere);
  }
  return finish[numLaps];
}

