function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const count = int(1, 4);
    const tires = Array.from({ length: count }, () => [int(1, 20), int(2, 6)]);
    return [tires, int(1, 30), int(1, 10)];
  }
  const count = int(1, 2000);
  const fMax = rand() < 0.5 ? 100 : 100000;
  const rMax = rand() < 0.5 ? 4 : 100000;
  const tires = Array.from({ length: count }, () => [int(1, fMax), int(2, rMax)]);
  const changeTime = rand() < 0.5 ? int(1, 100) : int(1, 100000);
  return [tires, changeTime, int(500, 1000)];
}
